from collections import defaultdict

def group_by_key(rows: list[tuple[str, int]]) -> dict[str, list[int]]:
    grouped: dict[str, list[int]] = defaultdict(list)
    for key, val in rows:
        grouped[key].append(val)
    return dict(grouped)
