from dataclasses import dataclass

@dataclass(frozen=True, slots=True)
class RetryPolicy:
    attempts: int
    backoff_sec: float

    def delay_for(self, attempt: int) -> float:
        return self.backoff_sec * (2 ** max(0, attempt - 1))
